package com.gregtech.gregtech.client;
import com.gregtech.gregtech.registry.*;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.api.distmarker.Dist;
@EventBusSubscriber(modid = com.gregtech.gregtech.api.mod.GregTechIdentity.MOD_ID,bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public final class MetalChestClientSetup {@SubscribeEvent public static void renderers(net.neoforged.neoforge.client.event.EntityRenderersEvent.RegisterRenderers e){e.registerBlockEntityRenderer(GTBlockEntities.METAL_CHEST.get(),MetalChestRenderer::new);}@SubscribeEvent public static void extensions(net.neoforged.neoforge.client.extensions.common.RegisterClientExtensionsEvent e){for(var b:GTMetalChests.all())e.registerItem(new net.neoforged.neoforge.client.extensions.common.IClientItemExtensions(){@Override public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){return MetalChestItemRenderer.instance();}},b.get().asItem());}@SubscribeEvent public static void items(net.neoforged.neoforge.client.event.RegisterColorHandlersEvent.Item e){for(var b:GTMetalChests.all())e.register((s,t)->t==0?b.get().material().getColor():0xFFFFFF,b.get().asItem());}}
